import { createHmac } from "node:crypto";
import { test, expect } from "vitest";
import { verifyToken } from "../src/auth/jwt";

const b = (o: object) => Buffer.from(JSON.stringify(o)).toString("base64url");
const sign = (h: object, p: object, s = "k") => {
  const d = `${b(h)}.${b(p)}`;
  return `${d}.${createHmac("sha256", s).update(d).digest("base64url")}`;
};
const now = Math.floor(Date.now() / 1000);

test("valid", () => expect(verifyToken(sign({ alg: "HS256" }, { sub: "u", exp: now + 60 }), "k").sub).toBe("u"));
test("expired", () => expect(() => verifyToken(sign({ alg: "HS256" }, { sub: "u", exp: now - 1 }), "k")).toThrow("expired"));
test("wrong secret", () => expect(() => verifyToken(sign({ alg: "HS256" }, { sub: "u", exp: now + 60 }, "x"), "k")).toThrow("signature"));
test("alg none", () => expect(() => verifyToken(`${b({ alg: "none" })}.${b({ sub: "u", exp: now + 60 })}.`, "k")).toThrow("alg"));
test("tampered payload", () => {
  const [h, , s] = sign({ alg: "HS256" }, { sub: "u", exp: now + 60 }).split(".");
  expect(() => verifyToken(`${h}.${b({ sub: "admin", exp: now + 60 })}.${s}`, "k")).toThrow("signature");
});

